section.sourcecode:
X402Proof = {
  1 => bstr             ; the x402 PaymentPayload, verbatim (the JSON bytes
                        ;   an X-PAYMENT header would carry, base64-decoded):
                        ;   scheme/network + the signed EIP-3009 authorization
}

PayDispute = { ; msg-type 0x0405; either party 1 => bstr .size 16, ; dispute-id (fresh) 2 => bstr .size 16, ; invoice-id under dispute 3 => uint, ; claim code (registry, §8): ; 0 non-delivery, 1 output-mismatch, ; 2 non-payment, 3 overbilling, ; 4 terms breach 4 => PayAgreeRef, ; the governing agreement (§3.1) — ; anchors quote, terms, cap, task ? 5 => bstr .size 32, ; TaskID, if the agreement is bound ? 6 => tstr .size (0..1024), ; free-text statement (never evidence) 7 => Timestamp }
PayDisputeEvidence = { ; msg-type 0x0406; both parties 1 => bstr .size 16, ; dispute-id 2 => [+ EvidenceItem], ? 3 => bool ; more available (chunk under } ; FLOW_CREDIT, core §8.1)
EvidenceItem = { 1 => uint, ; kind (registry, §8): ; 0 PAY_QUOTE envelope ; 1 PAY_AGREE envelope ; 2 PAY_INVOICE envelope ; 3 PAY_PROOF envelope ; 4 PAY_RECEIPT envelope ; 5 countersigned checkpoint ; (Checkpoint + the requester ; countersignature, tasks §8.2) ; 6 COMPLETE envelope ; 7 ExecutionReceipt (dual-signed, ; trust §3) ; 8 method artifact (ledger entry, ; release-auth, x402 payload, ; gateway upstream evidence …) ; 9 CHUNK envelope (tasks §3) — ; delivered-transcript evidence ; for claim 1 2 => bstr, ; the artifact VERBATIM: for envelope ; kinds, the received envelope bytes ; (core I1 — never re-serialized) ? 3 => bstr .size 32 ; the session channel binding (CB) } ; under which an in-session envelope ; was signed — see §6.2
